"import torch\nfrom torch import nn\nfrom torch.nn import functional as F\ntorch.manual_seed(0)\nK, N, T = 5, 600, 50                  # 5 个知识点，600 个学生，每人做 50 题\np_learn = torch.tensor([0.15, 0.10, 0.20, 0.05, 0.12])   # 每做一次学会的概率\np_guess, p_slip = 0.2, 0.1            # 不会也蒙对的概率、会了却做错的概率\nknown = (torch.rand(N, K) < 0.2).float()   # 一开始就会的知识点\nsk = torch.randint(0, K, (N, T))       # 每一步做哪个知识点的题\nrs = torch.zeros(N, T)                 # 对错\ntruth = torch.zeros(N, T)              # 真实的答对概率（模型看不到）\nfor t in range(T):\n    oh = F.one_hot(sk[:, t], K).float()\n    k = (known * oh).sum(1)            # 这一题的知识点会不会\n    p = k * (1 - p_slip) + (1 - k) * p_guess\n    truth[:, t] = p\n    rs[:, t] = (torch.rand(N) < p).float()\n    learn = (torch.rand(N) < (oh * p_learn).sum(1)).float()\n    known = known + oh * (1 - known) * learn.unsqueeze(1)\nsk.shape, rs.shape, sk.dtype, rs.dtype",
